interface TopicSeed extends TopicOptions {
  id: string;
  title: string;
  subtopics: readonly string[];
}

interface SectionSeed {
  id: string;
  title: string;
  description: string;
  routeBase: string;
  topics: readonly TopicSeed[];
}

const slugify = (value: string) => value.toLowerCase().replace(/&/g, "and").replace(/\//g, " ").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const researchedTopicIds = new Set([
  "interview-framework", "requirements", "estimation", "core-system-properties", "request-path", "http", "rest", "idempotent-apis", "load-balancing", "cdn", "websockets", "rate-limiting", "data-modeling", "sql-vs-nosql", "database-indexes", "transactions", "isolation-levels", "replication", "sharding", "consistent-hashing", "consistency-models", "cap-theorem", "object-storage", "caching", "cache-aside", "cache-invalidation", "cache-stampedes", "message-queues", "pub-sub", "event-streaming", "partitions", "consumer-groups", "delivery-semantics", "kafka", "retries", "idempotency", "circuit-breaker", "distributed-locks", "saga", "multi-region", "observability", "fan-out", "job-schedulers", "transactional-outbox", "change-data-capture", "full-text-search", "geospatial-search", "unique-id-generation", "redis", "postgresql", "dynamodb", "flink",
]);

const verificationTopicIds = new Set([
  "graphql", "dns", "oauth-oidc", "jwt", "sessions-tokens", "api-abuse-ddos", "cassandra", "rabbitmq", "zookeeper", "etcd", "collaborative-editing", "bloom-filters", "hyperloglog", "count-min-sketch", "vector-search", "model-serving",
]);

function sourceMetadata(id: string, published = false): Pick<SystemDesignTopicManifest, "contentStatus" | "sourceCoverage"> {
  if (published) return { contentStatus: "published", sourceCoverage: { primarySources: true, interviewSources: true, needsAdditionalVerification: false } };
  if (verificationTopicIds.has(id)) return { contentStatus: "needs-research", sourceCoverage: { primarySources: false, interviewSources: true, needsAdditionalVerification: true } };
  if (researchedTopicIds.has(id)) return { contentStatus: "draft-ready", sourceCoverage: { primarySources: true, interviewSources: true, needsAdditionalVerification: false } };
  return { contentStatus: "researched", sourceCoverage: { primarySources: true, interviewSources: false, needsAdditionalVerification: true } };
}

function topic(seed: TopicSeed, section: Omit<SectionSeed, "topics">): SystemDesignTopicManifest {
  const visual = seed.visual ?? "none";
  const published = seed.published ?? false;
  const priority = seed.priority ?? "important";
  return {
    id: seed.id,
    slug: `/system-design/${section.routeBase}/${seed.slug ?? slugify(seed.title)}`,
    title: seed.title,
    navigationTitle: seed.navigationTitle,
    sectionId: section.id,
    section: section.title,
    description: seed.description ?? `${seed.title} framed around the choices, trade-offs, and follow-up questions that matter in a System Design interview.`,
    priority,
    publishingPhase: seed.phase ?? (priority === "advanced" ? 3 : priority === "important" ? 2 : 1),
    estimatedMinutes: seed.minutes ?? 20,
    prerequisites: seed.prerequisites ?? [],
    levelPriority: { sde1: priority, sde2: priority, senior: priority, staff: priority, ...seed.levels },
    rolePriority: { backend: priority, fullstack: priority, infrastructure: priority, data: priority, ml: priority, ...seed.roles },
    roleReason: seed.roleReason ?? {},
    subtopics: seed.subtopics.map((title, index) => ({
      id: `${seed.id}-${slugify(title)}`,
      title,
      textRequired: true,
      exampleRequired: index === 0 || Boolean(seed.exampleType),
      visual: index === 0 ? visual : "none",
      visualDescription: index === 0 ? seed.visualDescription : undefined,
    })),
    examples: [{
      type: seed.exampleType ?? "comparison",
      description: seed.exampleDescription ?? `Use an interview scenario to show when ${seed.title} changes an architecture decision.`,
    }],
    visual: { type: visual, description: seed.visualDescription },
    relatedTopics: seed.relatedTopics ?? [],
    practiceProblems: [],
    ...sourceMetadata(seed.id, published),
    depth: { default: "interview", available: ["quick", "interview", "deep-dive"], deepDiveRecommendedFor: ["senior", "staff"] },
    published,
    lastReviewed: seed.lastReviewed,
  };
}

