const capacityPracticeIds = new Set(["url-shortener", "pastebin", "chat-system", "news-feed", "web-crawler", "cloud-file-storage", "video-streaming", "ride-sharing", "metrics-platform", "kafka-platform", "search-engine", "event-analytics"]);

function practice(id: string, title: string, group: string, options: PracticeOptions = {}): SystemDesignPracticeProblemManifest {
  const priority = options.priority ?? (options.difficulty === "advanced" ? "advanced" : "important");
  const difficulty = options.difficulty ?? "intermediate";
  const defaultRolePriority: Record<SystemDesignTargetRole, SystemDesignTopicPriority> = { backend: priority, fullstack: priority, infrastructure: priority, data: priority, ml: priority };
  const defaultLevelPriority: Record<SystemDesignLevel, SystemDesignTopicPriority> = { sde1: priority, sde2: priority, senior: priority, staff: priority };
  return {
    id,
    slug: `/system-design/problems/${id}`,
    title,
    group,
    priority,
    publishingPhase: options.phase ?? (priority === "must-know" ? 1 : priority === "important" ? 2 : 3),
    difficulty,
    prerequisites: options.concepts ?? ["interview-framework", "requirements", "estimation"],
    concepts: options.concepts ?? ["requirements", "estimation", "data-modeling"],
    rolePriority: { ...defaultRolePriority, ...options.roles },
    levelPriority: { ...defaultLevelPriority, ...options.levels },
    estimatedMinutes: options.minutes ?? publishedPracticeMinutes[id] ?? (difficulty === "foundation" ? 30 : difficulty === "advanced" || difficulty === "specialized" ? 50 : 40),
    capacityEstimationNeeded: options.capacity ?? capacityPracticeIds.has(id),
    apiDesignNeeded: options.api ?? true,
    dataModelNeeded: options.data ?? true,
    architectureDiagramNeeded: true,
    deepDiveSections: options.deepDives ?? ["Bottlenecks and scaling", "Failure modes", "Trade-offs"],
    interviewerFollowUps: options.followUps ?? ["Scale change", "Failure and recovery", "Consistency and cost"],
    contentStatus: publishedPracticeIds.has(id) ? "published" : options.status ?? "researched",
    lastReviewed: publishedPracticeIds.has(id) ? "2026-08-14" : undefined,
  };
}

