const practiceProblems = practiceProblemSeeds;
const practiceIdsByTopic = new Map<string, string[]>();
for (const problem of practiceProblems) for (const topicId of problem.concepts) practiceIdsByTopic.set(topicId, [...(practiceIdsByTopic.get(topicId) ?? []), problem.id]);

const allRawTopics = topicSections.flatMap((section) => section.topics);
const dependentTopics = new Map<string, string[]>();
for (const item of allRawTopics) for (const prerequisite of item.prerequisites) dependentTopics.set(prerequisite, [...(dependentTopics.get(prerequisite) ?? []), item.id]);

export const systemDesignManifestSections: readonly SystemDesignSectionManifest[] = topicSections.map((section) => ({
  ...section,
  topics: section.topics.map((item) => ({
    ...item,
    relatedTopics: [...new Set([...item.relatedTopics, ...item.prerequisites, ...(dependentTopics.get(item.id) ?? [])])],
    practiceProblems: practiceIdsByTopic.get(item.id) ?? [],
  })),
}));

export const systemDesignTopicManifest: readonly SystemDesignTopicManifest[] = systemDesignManifestSections.flatMap((section) => section.topics);
export const systemDesignPracticeProblemManifest: readonly SystemDesignPracticeProblemManifest[] = practiceProblems;

export const systemDesignManifest = {
  version: 1,
  purpose: "Canonical interview-oriented System Design curriculum, publishing status, personalization metadata, and practice connections.",
  sections: systemDesignManifestSections,
  topics: systemDesignTopicManifest,
  practiceProblems: systemDesignPracticeProblemManifest,
} as const;
